/** Serialized artifact payload returned by the workspace protocol. */
export type ArtifactBlob = {
    /** Exact artifact version. */
    readonly version: ArtifactVersion;
    /** Serialized artifact payload bytes. */
    readonly bytes: Uint8Array | readonly number[];
};

export const ArtifactBlob = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: ArtifactBlob): void {
        encodeArtifactBlob(writer, value);
    },

    /** Decode one ArtifactBlob. */
    decode(reader: BinaryReader): ArtifactBlob {
        return decodeArtifactBlob(reader);
    },

    /** Return this value as JSON. */
    toJson(value: ArtifactBlob): Json {
        return toJsonArtifactBlob(value);
    },

    /** Return one ArtifactBlob from one JSON value. */
    fromJson(value: Json): ArtifactBlob {
        return fromJsonArtifactBlob(value);
    },
};

/** Encode one ArtifactBlob. */
export function encodeArtifactBlob(writer: BinaryWriter, value: ArtifactBlob): void {
    encodeArtifactVersion(writer, value.version);
    writer.writeByteSlice(value.bytes);
}

/** Decode one ArtifactBlob. */
export function decodeArtifactBlob(reader: BinaryReader): ArtifactBlob {
    const version = decodeArtifactVersion(reader);
    const bytes = reader.readByteSlice();

    return {
        version,
        bytes,
    };
}

/** Return one JSON value for one ArtifactBlob. */
export function toJsonArtifactBlob(value: ArtifactBlob): Json {
    return {
        version: toJsonArtifactVersion(value.version),
        bytes: bytesToJson(value.bytes),
    };
}

/** Return one ArtifactBlob from one JSON value. */
export function fromJsonArtifactBlob(value: Json): ArtifactBlob {
    const object = jsonObject(value);

    return {
        version: fromJsonArtifactVersion(jsonField(object, "version")),
        bytes: bytesFromJson(jsonField(object, "bytes")),
    };
}
